-- The Lost Isles: the Gnomeregan Stealth Fighters (39039) carry a Gnomeregan Pilot (39041) on seat 0 and a Machine Gun
-- (40785) on seat 1 as their vehicle accessories in Legends of Azeroth 5.4.8, but the fighters had no spellclick row,
-- which our accessory loader needs, so no pilot or gun was ever seated and all 47 stood loose at their fighters. Add the
-- accessories and the Legends of Azeroth click row (46598, cast flags 1, user type 0); the fighters get no click flag
-- there either.
-- All 47 pilots are 0.76 yards and all 47 guns 0.01 yards from a fighter with the same orientation, phase and spawn mask.
-- Both entries have no other spawn, are not pooled, in an event, formation, addon, path, linked respawn or smart script,
-- and are not summoned by a script or summon group. Legends of Azeroth, the only reference, has none of them within 13
-- yards of a fighter. Ten of the fighters stand on the same spot as another one; they and their riders are left as they
-- are (riders on a shared spot are listed under the lowest vehicle guid).

DELETE FROM `vehicle_template_accessory` WHERE `entry` IN (39039);
INSERT INTO `vehicle_template_accessory` (`entry`, `accessory_entry`, `seat_id`, `minion`, `description`, `summontype`, `summontimer`) VALUES
(39039, 39041, 0, 1, 'Gnomeregan Stealth Fighter', 6, 30000),
(39039, 40785, 1, 1, 'Gnomeregan Stealth Fighter', 6, 30000);

DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (39039);
INSERT INTO `npc_spellclick_spells` (`npc_entry`, `spell_id`, `cast_flags`, `user_type`) VALUES
